import { DomainError } from "./errors";

export const ORDER_STATES = ["placed", "paid", "packed", "shipped", "delivered"] as const;
export type OrderState = (typeof ORDER_STATES)[number];
export type OrderStatus = OrderState | "cancelled";

export interface OrderLine {
  readonly productId: string;
  readonly quantity: number;
}

export interface Order {
  readonly id: string;
  readonly lines: readonly OrderLine[];
  status: OrderStatus;
  readonly createdAt: string;
}

export function isOrderStatus(value: string): value is OrderStatus {
  return value === "cancelled" || (ORDER_STATES as readonly string[]).includes(value);
}

export function nextState(status: OrderStatus): OrderState {
  if (status === "cancelled") {
    throw new DomainError("invalid_transition", "Order is cancelled");
  }
  const next = ORDER_STATES[ORDER_STATES.indexOf(status) + 1];
  if (next === undefined) {
    throw new DomainError("invalid_transition", `Order is already ${status}`);
  }
  return next;
}

export function assertCancellable(order: Order): void {
  if (order.status !== "placed" && order.status !== "paid" && order.status !== "packed") {
    throw new DomainError("invalid_transition", `Order cannot be cancelled when ${order.status}`);
  }
}

