import { DomainError } from "./errors";

export interface Product {
  readonly id: string;
  readonly name: string;
  onHand: number;
  reserved: number;
}

export interface StockLevel {
  productId: string;
  name: string;
  onHand: number;
  reserved: number;
  available: number;
}

export function availableOf(product: Product): number {
  return product.onHand - product.reserved;
}

export function reserve(product: Product, quantity: number): void {
  if (availableOf(product) < quantity) {
    throw new DomainError("insufficient_stock", `Insufficient stock for product ${product.id}`);
  }
  product.reserved += quantity;
}

export function release(product: Product, quantity: number): void {
  product.reserved -= quantity;
}

/** Shipped goods leave the warehouse: they are no longer on hand nor reserved. */
export function dispatch(product: Product, quantity: number): void {
  product.reserved -= quantity;
  product.onHand -= quantity;
}

export function toStockLevel(product: Product): StockLevel {
  return {
    productId: product.id,
    name: product.name,
    onHand: product.onHand,
    reserved: product.reserved,
    available: availableOf(product),
  };
}

